import type { PlanarState } from "../../src/features/tools/planar-kit/contract";
import { constructionObject, constructionObjects, insertConstructionVertex, removeConstruction } from "../../src/features/tools/plane-construction/model";
import { addConcaveOverlapMaterial, assignConcaveOverlap, createConcaveOverlapGeometry, createConcaveOverlapState, setConcaveOverlapField, settleConcaveOverlap } from "../../src/features/tools/plane-overlap/concave-model";
import { createOverlapState } from "../../src/features/tools/plane-overlap/model";

export function planeOverlapConcaveCases() {
  const initial = createConcaveOverlapState(), id = initial.params.pairA;
  const cases: { label: string; accepted: boolean; scene: { toolId: string; contentVersion: string; payload: { title: string; initial: PlanarState } } }[] = [];
  const add = (label: string, state: PlanarState, accepted = true, version = "plane-overlap-lesson-v3") => cases.push({ label, accepted, scene: { toolId: "plane-overlap", contentVersion: version, payload: { title: "Concave overlap exploration", initial: state } } });
  const invalid = (label: string, change: (state: PlanarState) => void) => { const state = structuredClone(initial); change(state); add(label, state, false); };
  add("default", initial);
  const visible = { ...setConcaveOverlapField(initial, "region", 3), flags: { ...initial.flags, measures: true } }; add("visible", visible);
  add("intersection", setConcaveOverlapField(visible, "region", 1)); add("union", setConcaveOverlapField(visible, "region", 2));
  add("rotated", setConcaveOverlapField(visible, "angle", 43));
  add("reflected", { ...visible, params: { ...visible.params, [`flip.${id}`]: -1 } });
  add("collinear", settleConcaveOverlap(visible, insertConstructionVertex({ ...visible, flags: { ...visible.flags, edit: true } }, `edge.${id}.0`)));
  const clockwise = structuredClone(visible), vertices = constructionObject(clockwise, id)!.vertices.reverse();
  vertices.forEach((point, index) => { clockwise.points[`vertex.${id}.${index}`] = point; }); add("clockwise", clockwise);
  add("second-concave", assignConcaveOverlap(addConcaveOverlapMaterial(visible, "u-paper"), "pairB"));
  const unpaired = settleConcaveOverlap(visible, removeConstruction(visible)); add("missing-B", unpaired);
  const empty = settleConcaveOverlap(unpaired, removeConstruction(unpaired)); add("empty", empty);
  let full = empty;
  const polygon = (count: number) => Array.from({ length: count }, (_, index) => ({ x: 420 + (index % 2 ? 70 : 130) * Math.cos(index * 2 * Math.PI / count), y: 310 + (index % 2 ? 70 : 130) * Math.sin(index * 2 * Math.PI / count) }));
  for (let i = 0; i < 16; i++) full = createConcaveOverlapGeometry(full, "polygon", polygon(12))!;
  add("capacity-16-papers-192-points", full);
  let maximum = empty;
  for (let i = 0; i < 6; i++) maximum = createConcaveOverlapGeometry(maximum, "polygon", polygon(32))!;
  add("capacity-32-points-per-paper", maximum);
  const excess = structuredClone(full), target = constructionObjects(excess)[0];
  excess.params[`count.${target.id}`] = 13;
  excess.points[`vertex.${target.id}.12`] = { x: (target.vertices[11].x + target.vertices[0].x) / 2, y: (target.vertices[11].y + target.vertices[0].y) / 2 };
  add("over-total-points", excess, false);
  invalid("unknown-param", (state) => { state.params.extra = 1; });
  invalid("unknown-flag", (state) => { state.flags.extra = true; });
  invalid("unknown-point", (state) => { state.points.intersection = { x: 1, y: 1 }; });
  invalid("unknown-state-key", (state) => { Object.assign(state, { derivedArea: 42 }); });
  invalid("missing-pair", (state) => { delete state.params.pairA; });
  invalid("orphan-pair", (state) => { state.params.pairB = 99998; });
  invalid("same-pair", (state) => { state.params.pairB = state.params.pairA; });
  invalid("fractional-pair", (state) => { state.params.pairA = 1.5; });
  invalid("string-pair", (state) => { Object.assign(state.params, { pairA: String(id) }); });
  invalid("null-pair", (state) => { Object.assign(state.params, { pairA: null }); });
  invalid("region-range", (state) => { state.params.region = 4; });
  invalid("region-fraction", (state) => { state.params.region = 1.5; });
  invalid("string-region", (state) => { Object.assign(state.params, { region: "1" }); });
  invalid("string-flag", (state) => { Object.assign(state.flags, { edit: "false" }); });
  invalid("frame-basis", (state) => { state.params[`frameA.${id}`] = 1; });
  invalid("noncanonical-id", (state) => { state.params["kind.01"] = 0; });
  invalid("extra-point-key", (state) => { Object.assign(state.points[`vertex.${id}.0`], { z: 0 }); });
  invalid("invalid-mark", (state) => { state.marks = [`vertex.${id}.31`]; });
  invalid("circle", (state) => { state.params[`kind.${id}`] = 2; });
  invalid("life-detail", (state) => { state.params[`life.${id}`] = 1; state.params[`detail.${id}`] = 1; });
  invalid("duplicate-vertex", (state) => { state.points[`vertex.${id}.1`] = { ...state.points[`vertex.${id}.0`] }; });
  invalid("self-crossing", (state) => {
    const first = state.points[`vertex.${id}.0`]; state.points[`vertex.${id}.0`] = state.points[`vertex.${id}.2`]; state.points[`vertex.${id}.2`] = first;
  });
  invalid("collinear-backtracking", (state) => { state.points[`vertex.${id}.2`] = { x: 0, y: -120 }; });
  invalid("phase", (state) => { state.phase = 1; });
  add("v2-as-v3", createOverlapState(), false);
  add("v3-as-v2", initial, false, "plane-overlap-lesson-v2");
  return cases;
}
